/**
 * Dari strings — T6.3 batch 4.
 *
 * Same keys, same order as en.js. Values use Western digits (0-9);
 * brand/product/technical terms stay in Latin script (Luminous StockHaven,
 * Stripe, Excel, CSV, SKU, UPC, ISBN, Bluetooth, Wi-Fi, USB, AirPrint).
 * English plural-agreement markers ({s}, {plural}, {suffix}, {us}, {cs},
 * {ps}, {fs}, {rs}) are OMITTED here — the plural lives in the word form,
 * and keeping one would render a stray Latin letter.
 *
 * Translations are Muse-generated, not professionally translated — a native
 * speaker spotting something off later gets it fixed.
 */
