  "plans.intro": "یک حساب، هر پلانی را که انتخاب کنید — Business تا پنج تجارت را پوشش می‌دهد. قیمت‌ها ماهانه به دالر امریکایی هستند و مشتریان جدید واجد شرایط وب‌سایت می‌توانند یک دوره آزمایشی هفت‌روزه در میان Essentials و Business دریافت کنند. ارتقای یک اشتراک موجود Essentials به Business دوره آزمایشی را از نو شروع نمی‌کند و دوره آزمایشی رایگان دیگری نمی‌سازد. قیمت‌های پلان وب‌سایت قبل از مالیه‌های قابل اجرا، در صورت وجود، هستند. شارژ دقیق شما قبل از اینکه اشتراک را اجازه دهید نشان داده خواهد شد.",
