  "exports.eyebrow": "داده‌ها",
  "exports.title": "صادرات و نسخه‌های پشتیبان",
  "exports.subtitleStart": "دانلودها همیشه محدود به",
  "exports.subtitleRest": " هستند. هر فایل با نام تجارت و تاریخی که ساخته شده برچسب‌گذاری می‌شود.",
  "exports.createBusinessFirst": "نخست یک تجارت بسازید — صادرات به یک تجارت تعلق دارند، نه به برنامه.",
  "exports.lockedTitle": "صادرات CSV و Excel یک ویژگی Business است",
  "exports.lockedDesc": "محیط کاری شما روی پلان Essentials است. Business صادرات CSV و Excel، ارزش‌گذاری موجودی، محصولات و کارمندان نامحدود، تأمین‌کنندگان، خرید و بسته‌ها را اضافه می‌کند.",
  "exports.seeBusiness": "ببینید Business چه چیزهایی را شامل می‌شود",
  "exports.whatTheseAre": "این فایل‌ها چه هستند",
  "exports.about1": "هر مجموعه داده به عنوان CSV یا یک کتاب کار واقعی Excel (.xlsx) می‌آید — کتاب کار کامل موجودی فقط Excel است، با یک ورق برای هر مجموعه داده. فایل‌های CSV در Excel، Numbers، Google Sheets و بیشتر برنامه‌های موجودی باز می‌شوند. متن UTF-8، کاماهای نقل‌قول‌شده، شکست خط در یادداشت‌ها و صفرهای ابتدایی در کودها همه حفظ می‌شوند و خانه‌هایی که مانند یک فرمول شروع می‌شوند خنثی می‌شوند تا یک صفحه گسترده آن‌ها را به عنوان متن باز کند.",
  "exports.about2": "در فایل‌های Excel، SKUها، UPCها، ISBNها و بارکودها خانه‌های متنی هستند — هرگز نماد علمی و هرگز صفرهای بریده‌شده — با عرض ستون‌ها، فیلترهای سرخط و فرمت‌های ارز یا مقدار اعمال‌شده. کتاب کار کامل موجودی محصولات، سطوح موجودی، موقعیت‌ها و حرکات را روی ورق‌های جدا نگه می‌دارد.",
  "exports.about3": "صادرات بسیار بزرگ در 20,000 ردیف برای هر مجموعه داده متوقف می‌شوند — وقتی این اتفاق می‌افتد نام فایل آن را می‌گوید (truncated-20000)، پس یک فایل جزئی هرگز به عنوان کامل نمی‌گذرد.",
  "exports.about4": "یک نسخه پشتیبان یک عکس فوری از داده‌های شما است، نه یک بازیابی با یک کلیک. بازیابی آن یک کار دستی و نخست بررسی است، پس فایل را امن نگه دارید — هنوز هیچ چیزی در برنامه نمی‌تواند یک تجارت حذف‌شده را از آن دوباره بسازد. کود برنامه و نسخه‌های پشتیبان پلتفرم Base44 جدا از این فایل‌ها انجام می‌شوند.",
  "exports.about5": "عکس‌ها و پیوست‌ها به عنوان لینک‌های ذخیره‌شده آن‌ها فهرست می‌شوند — خود فایل‌های تصویر در دانلود بسته‌بندی نمی‌شوند.",
  "exports.backupTitle": "نسخه پشتیبان کامل",
  "exports.backupDesc": "یک فایل با محصولات، موقعیت‌ها، سطوح موجودی، دفتر کامل حرکات، تأمین‌کنندگان، خرید، سفارشات، برگشتی‌ها، شمارش‌ها و فهرست‌های این تجارت — به علاوه تنظیمات مشخصات آن. آن را در جایی که کنترل می‌کنید نگه دارید.",
  "exports.backupIncludes1": "محصولات، کودها، هزینه‌ها و یادداشت‌ها",
