  "settings.cancelSubscription": "لغو اشتراک",
  "settings.cancelTerms.appleLink": "دستورالعمل‌های لغو Apple",
  "settings.cancelTerms.googlePlayLink": "دستورالعمل‌های لغو Google Play",
  "settings.cancelTerms.graceTitle": "پس از پایان دوره پرداخت‌شده شما — مهلت 15 روزه، سپس حذف:",
  "settings.cancelTerms.intro": "این‌ها شرایط اشتراک‌های پرداخت‌شده Luminous StockHaven هستند. صورت‌حساب اشتراک وب‌سایت از طریق Stripe است. شما می‌توانید اشتراک خود را هر وقت خودتان با استفاده از دکمه لغو اشتراک در زیر لغو کنید — هیچ تأیید کارمندی لازم نیست. درخواست‌های لغو و بازپرداخت نیز می‌توانند از طریق تماس رسمی پشتیبانی مشتری، theluminousbookshop@outlook.com، انجام شوند.",
  "settings.cancelTerms.noApprovalBody": "شما می‌توانید اشتراک خود را هر وقت خودتان لغو کنید. هیچ تأیید کارمندی لازم نیست. تمدیدهای آینده فقط پس از تأیید لغو توسط ارائه‌دهنده صورت‌حساب متوقف می‌شوند.",
  "settings.cancelTerms.noApprovalTitle": "لغو بدون تأیید:",
  "settings.cancelTerms.paymentBody": "برای دوره‌های آزمایشی پرداخت‌شده، دوره آزمایشی هفت‌روزه هنگام ثبت‌نام به یک روش پرداخت نیاز دارد. مگر اینکه در مهلت لغو دوره آزمایشی قابل اجرا لغو شود، پلان ماهانه انتخاب‌شده پس از دوره آزمایشی به طور خودکار شارژ خواهد شد. قیمت، اولین تاریخ صورت‌حساب و مهلت لغو خاص ارائه‌دهنده باید هنگام ثبت‌نام نشان داده شوند. صورت‌حساب دوره آزمایشی از طریق Stripe است.",
  "settings.cancelTerms.paymentTitle": "روش پرداخت و تمدید خودکار:",
  "settings.cancelTerms.remainingBody": "اگر قبلاً برای یک دوره صورت‌حساب پرداخت کرده‌اید، می‌توانید دسترسی را تا آن تاریخ پرداخت‌شده تأییدشده نگه دارید. پایان زودتر نیاز به تأیید مناسب ارائه‌دهنده و هر رسیدگی بازپرداخت قابل اجرا دارد. دسترسی دوره آزمایشی رایگان طبق تاریخ پایان دوره آزمایشی تأییدشده توسط ارائه‌دهنده پایان می‌یابد.",
  "settings.cancelTerms.remainingTitle": "دسترسی باقی‌مانده:",
  "settings.cancelTerms.storesBody": "اگر هرگز از طریق Google Play یا Apple App Store اشتراک کنید، اشتراک شما توسط آن دکان صورت‌حساب و مدیریت می‌شود. ممکن است نیاز داشته باشید آن را مستقیم در بخش اشتراک‌های همان حساب Google یا Apple که برای اشتراک استفاده شده لغو کنید. لغو یک اشتراک جداگانه وب‌سایت، حذف این برنامه، یا درخواست حذف حساب Luminous StockHaven به طور خودکار یک اشتراک صورت‌حساب‌شده توسط دکان را لغو نمی‌کند. رسید خرید خود را بررسی کنید تا تأیید کنید چه کسی از شما صورت‌حساب می‌گیرد.",
  "settings.cancelTerms.storesTitle": "اشتراک‌های Google Play و Apple App Store (اگر هرگز از طریق یک دکان اشتراک کنید):",
  "settings.cancelTerms.title": "شرایط و ضوابط لغو",
  "settings.cancelTerms.trialBody": "دوره آزمایشی هفت‌روزه فقط یک بار برای هر مشتری واجد شرایط می‌تواند استفاده شود. لغو یک دوره آزمایشی یا اشتراک دوره آزمایشی دیگری نمی‌دهد؛ مشتریان برگشتی باید یک اشتراک پرداخت‌شده انتخاب کنند.",
  "settings.cancelTerms.trialTitle": "یک دوره آزمایشی رایگان:",
  "settings.canceled.endsOn": "این اشتراک لغو شده است و در {date} پایان می‌یابد. تا آن زمان دسترسی کامل را نگه می‌دارید.",
  "settings.delete.checking": "در حال بررسی یک درخواست حذف موجود…",
  "settings.delete.description": "درخواست حذف حساب ورود Luminous StockHaven خود را بدهید.",
  "settings.delete.dialogDescription": "این درخواست بررسی حذف حساب را می‌دهد. ورود یا موجودی شما را بلافاصله حذف نمی‌کند و هیچ اشتراک Stripe را لغو نمی‌کند. {word} را تایپ کنید تا تأیید کنید می‌خواهید درخواست را ارسال کنید.",
  "settings.delete.dialogTitle": "درخواست حذف حساب",
  "settings.delete.enterDelete": "{word} را برای تأیید وارد کنید",
  "settings.delete.exportFirst": "اگر نیاز دارید سوابق خود را نگه دارید، نخست موجودی خود را صادر کنید.",
  "settings.delete.intro": "ارسال یک درخواست حساب، تجارت‌ها یا موجودی شما را بلافاصله حذف نمی‌کند. درخواست‌ها جدا بررسی می‌شوند قبل از اینکه حذف بتواند تکمیل شود. این درخواست یک اشتراک Stripe را لغو نمی‌کند یا صورت‌حساب آینده را متوقف نمی‌کند؛ لغو اشتراک باید جدا از طریق ارائه‌دهنده صورت‌حساب انجام شود.",
  "settings.delete.keepAccount": "نگه داشتن حساب",
