  "settings.switcher.upgrade": "ارتقا",
  "settings.title": "تنظیمات",
  "settings.trial.cancelKeeps": "لغو در جریان دوره آزمایشی 7 روز کامل شما را نگه می‌دارد — دسترسی در {date} پایان می‌یابد و از شما شارژ نخواهد شد.",
  "staff.access.noSeatBody": "حساب شما هیچ جای کارمندی برای این تجارت ندارد، پس موجودی آن بسته می‌ماند. از مالک بخواهید شما را در کارمندان و نقش‌ها اضافه کند.",
  "staff.access.noSeatTitle": "این تجارت برای ورود شما باز نیست",
  "staff.access.pendingBody": "این تجارت یک دعوت برای ایمیل شما دارد که فعال نشده است. از مالک بخواهید وضعیت کارمندی شما را به فعال تنظیم کند. تا آن زمان هیچ چیزی در اینجا قابل مشاهده نیست.",
  "staff.access.pendingTitle": "دعوت شما هنوز فعال نیست",
  "staff.access.signOut": "خارج شدن",
  "staff.access.suspendedBody": "یک مدیر این حساب کارمندی را برای تجارت فعال معلق کرده است. از آن‌ها بخواهید شما را دوباره به فعال تنظیم کنند، سپس دوباره وارد شوید.",
  "staff.access.suspendedTitle": "دسترسی شما متوقف شده است",
  "staff.addFirst": "اضافه کردن اولین کارمند",
  "staff.addMember": "اضافه کردن کارمند",
  "staff.emptyBody": "یک شخص را اضافه کنید، به آن‌ها یک نقش و اجازه‌هایی که با آن می‌رود بدهید، و آن‌ها با ایمیل دعوت می‌شوند تا به این تجارت وارد شوند.",
  "staff.emptyTitle": "هنوز هیچ کارمندی نیست",
  "staff.eyebrow": "تیم",
  "staff.how.p1": "هر عضو یک نقش و فهرست اجازه‌های خودش را دارد، پس می‌توانید از یک نقش شروع کنید و یک چیز را بدون ساختن یک نقش جدید تغییر دهید. ویرایش یک نقش اعضایی را که قبلاً روی آن هستند دوباره نمی‌نویسد — یک عضو را باز کنید تا پیش‌فرض‌های نقش آن‌ها دوباره اجرا شود.",
  "staff.how.p2": "نقش‌های سفارشی یک ویژگی Business هستند: Essentials از پنج نقش داخلی استفاده می‌کند (مالک، مدیر، کارمند موجودی، کارمند فروش، بیننده).",
  "staff.how.p3": "دعوت‌ها با ایمیل فرستاده می‌شوند. یک عضو فقط زمانی می‌تواند وارد شود که قبول کند، و حذف یک نفر از این فهرست حساب برنامه آن‌ها را حذف نمی‌کند.",
  "staff.how.p4": "یک دکان موقعیتی است که یک شخص به آن اختصاص داده شده است. روی کارت آن‌ها ثبت می‌شود؛ آنچه می‌توانند باز کنند هنوز توسط نقش و اجازه‌های آن‌ها تصمیم گرفته می‌شود.",
  "staff.how.p5": "اجازه‌ها تصمیم می‌گیرند هر شخص چه چیزی را می‌تواند باز کند: اجناس منو خارج از نقش آن‌ها پنهان هستند و یک آدرس مسدودشده به جای صفحه یک اطلاعیه «روی نقش شما نیست» نشان می‌دهد. یک تغییر دفعه بعد که آن شخص برنامه را بار کند اجرا می‌شود؛ معلق کردن یک عضو آن‌ها را به طور کامل بیرون می‌کند.",
  "staff.how.p6": "مدیران می‌توانند همه داده‌ها را ببینند و تغییر دهند، کاربران برنامه و نقش‌ها را مدیریت کنند و هرگز توسط یک نقش کارمندی محدود نمی‌شوند. کسی بدون سابقه کارمندی — مالک یک تجارت جدید — دسترسی کامل را نگه می‌دارد.",
  "staff.howTitle": "کارمندان و نقش‌ها چگونه کار می‌کنند",
